diff --git a/fastcache.go b/fastcache.go
index 046af6c..2b118f6 100644
--- a/fastcache.go
+++ b/fastcache.go
@@ -284,150 +284,3 @@ func (b *bucket) cleanLocked() {
 		// Re-create b.m with valid items, which weren't expired yet instead of deleting expired items from b.m.
 		// This should reduce memory fragmentation and the number Go objects behind b.m.
 		// See https://github.com/VictoriaMetrics/VictoriaMetrics/issues/5379
-		bmNew := make(map[uint64]uint64, newItems)
-		for k, v := range bm {
-			gen := v >> bucketSizeBits
-			idx := v & ((1 << bucketSizeBits) - 1)
-			if (gen+1 == bGen || gen == maxGen && bGen == 1) && idx >= bIdx || gen == bGen && idx < bIdx {
-				bmNew[k] = v
-			}
-		}
-		b.m = bmNew
-	}
-}
-
-func (b *bucket) UpdateStats(s *Stats) {
-	s.GetCalls += atomic.LoadUint64(&b.getCalls)
-	s.SetCalls += atomic.LoadUint64(&b.setCalls)
-	s.Misses += atomic.LoadUint64(&b.misses)
-	s.Collisions += atomic.LoadUint64(&b.collisions)
-	s.Corruptions += atomic.LoadUint64(&b.corruptions)
-
-	b.mu.RLock()
-	s.EntriesCount += uint64(len(b.m))
-	bytesSize := uint64(0)
-	for _, chunk := range b.chunks {
-		bytesSize += uint64(cap(chunk))
-	}
-	s.BytesSize += bytesSize
-	s.MaxBytesSize += uint64(len(b.chunks)) * chunkSize
-	b.mu.RUnlock()
-}
-
-func (b *bucket) Set(k, v []byte, h uint64) {
-	atomic.AddUint64(&b.setCalls, 1)
-	if len(k) >= (1<<16) || len(v) >= (1<<16) {
-		// Too big key or value - its length cannot be encoded
-		// with 2 bytes (see below). Skip the entry.
-		return
-	}
-	var kvLenBuf [4]byte
-	kvLenBuf[0] = byte(uint16(len(k)) >> 8)
-	kvLenBuf[1] = byte(len(k))
-	kvLenBuf[2] = byte(uint16(len(v)) >> 8)
-	kvLenBuf[3] = byte(len(v))
-	kvLen := uint64(len(kvLenBuf) + len(k) + len(v))
-	if kvLen >= chunkSize {
-		// Do not store too big keys and values, since they do not
-		// fit a chunk.
-		return
-	}
-
-	chunks := b.chunks
-	needClean := false
-	b.mu.Lock()
-	idx := b.idx
-	idxNew := idx + kvLen
-	chunkIdx := idx / chunkSize
-	chunkIdxNew := idxNew / chunkSize
-	if chunkIdxNew > chunkIdx {
-		if chunkIdxNew >= uint64(len(chunks)) {
-			idx = 0
-			idxNew = kvLen
-			chunkIdx = 0
-			b.gen++
-			if b.gen&((1<<genSizeBits)-1) == 0 {
-				b.gen++
-			}
-			needClean = true
-		} else {
-			idx = chunkIdxNew * chunkSize
-			idxNew = idx + kvLen
-			chunkIdx = chunkIdxNew
-		}
-		chunks[chunkIdx] = chunks[chunkIdx][:0]
-	}
-	chunk := chunks[chunkIdx]
-	if chunk == nil {
-		chunk = getChunk()
-		chunk = chunk[:0]
-	}
-	chunk = append(chunk, kvLenBuf[:]...)
-	chunk = append(chunk, k...)
-	chunk = append(chunk, v...)
-	chunks[chunkIdx] = chunk
-	b.m[h] = idx | (b.gen << bucketSizeBits)
-	b.idx = idxNew
-	if needClean {
-		b.cleanLocked()
-	}
-	b.mu.Unlock()
-}
-
-func (b *bucket) Get(dst, k []byte, h uint64, returnDst bool) ([]byte, bool) {
-	atomic.AddUint64(&b.getCalls, 1)
-	found := false
-	chunks := b.chunks
-	b.mu.RLock()
-	v := b.m[h]
-	bGen := b.gen & ((1 << genSizeBits) - 1)
-	if v > 0 {
-		gen := v >> bucketSizeBits
-		idx := v & ((1 << bucketSizeBits) - 1)
-		if gen == bGen && idx < b.idx || gen+1 == bGen && idx >= b.idx || gen == maxGen && bGen == 1 && idx >= b.idx {
-			chunkIdx := idx / chunkSize
-			if chunkIdx >= uint64(len(chunks)) {
-				// Corrupted data during the load from file. Just skip it.
-				atomic.AddUint64(&b.corruptions, 1)
-				goto end
-			}
-			chunk := chunks[chunkIdx]
-			idx %= chunkSize
-			if idx+4 >= chunkSize {
-				// Corrupted data during the load from file. Just skip it.
-				atomic.AddUint64(&b.corruptions, 1)
-				goto end
-			}
-			kvLenBuf := chunk[idx : idx+4]
-			keyLen := (uint64(kvLenBuf[0]) << 8) | uint64(kvLenBuf[1])
-			valLen := (uint64(kvLenBuf[2]) << 8) | uint64(kvLenBuf[3])
-			idx += 4
-			if idx+keyLen+valLen >= chunkSize {
-				// Corrupted data during the load from file. Just skip it.
-				atomic.AddUint64(&b.corruptions, 1)
-				goto end
-			}
-			if string(k) == string(chunk[idx:idx+keyLen]) {
-				idx += keyLen
-				if returnDst {
-					dst = append(dst, chunk[idx:idx+valLen]...)
-				}
-				found = true
-			} else {
-				atomic.AddUint64(&b.collisions, 1)
-			}
-		}
-	}
-end:
-	b.mu.RUnlock()
-	if !found {
-		atomic.AddUint64(&b.misses, 1)
-	}
-	return dst, found
-}
-
-func (b *bucket) Del(h uint64) {
-	b.mu.Lock()
-	delete(b.m, h)
-	b.mu.Unlock()
-}

